// ---------- seed data (crafted so headline stats match the design: 32 / 21 / 7 / 4) ----------
function seedStudents() {
  const rows = [];
  let id = 1;
  const push = (lastName, acc, wpm) => {
    rows.push({
      id: id++,
      lastName,
      wpm,
      accuracy: acc,
      historyDate: "06-07-2026",
      birthMonth: "06",
      birthDay: String(10 + (id % 15)).padStart(2, "0"),
      birthYear: String(2016 + (id % 3)),
      classNumber: String((id % 10) + 1).padStart(2, "0"),
      expanded: false,
    });
  };
  push("Santos", 96, 112);
  push("Reyes", 61, 54);
  for (let i = 3; i <= 21; i++) push(`Surname ${i}`, 90 + (i % 10), 95 + (i % 30));
  for (let i = 22; i <= 28; i++) push(`Surname ${i}`, 75 + (i % 12), 70 + (i % 20));
  for (let i = 29; i <= 32; i++) push(`Surname ${i}`, 50 + (i % 15), 40 + (i % 15));
  return rows;
}

const API_URL = import.meta.env.VITE_API_URL || "http://localhost:5000";

async function apiErrorMessage(response, fallbackMessage) {
  const responseText = await response.text();
  try {
    return JSON.parse(responseText).message || fallbackMessage;
  } catch {
    return `${fallbackMessage} The API returned HTML instead of JSON. Make sure the backend is running at ${API_URL}.`;
  }
}

function learnerToStudent(learner) {
  const [birthYear = "", birthMonth = "", birthDay = ""] = (learner.birthdate || "").split("-");
  return {
    id: learner._id,
    lastName: learner.lastName,
    section: learner.section,
    birthMonth,
    birthDay,
    birthYear,
    wpm: 0,
    accuracy: 0,
    historyDate: "--",
    expanded: false,
  };
}

function riskOf(accuracy) {
  if (accuracy >= 90) return "low";
  if (accuracy >= 70) return "moderate";
  return "high";
}
const riskLabel = { low: "Low Risk", moderate: "Moderate Risk", high: "High Risk" };
